    const checkpointPath = join(dir, 'checkpoint.json');
    const records = Array.from({ length: 5 }, (_, seq) => JSON.stringify({ tenant: 'a', seq }));
    await writeFile(inputPath, [records[0], records[0], 'bad', ...records.slice(1)].join('\n') + '\n');
